import { useEffect, useMemo, useRef, useState } from 'react'
import type { ChangeEvent, CSSProperties, ReactNode } from 'react'
import { emptyVault, type CircuitPart, type ClassItem, type CodeProject, type FileItem, type LogicNode, type Note, type Priority, type Slide, type Task, type ThemeName, type VaultState, type ViewId } from './types'
import { getPrefs, loadVault, makeBackup, parseBackup, saveVault, setPref } from './lib/persistence'
import { themeVars, themes } from './lib/themes'
import './styles.css'

const nav: { id: ViewId; label: string; icon: string; group: string }[] = [
  { id: 'dashboard', label: 'Overview', icon: '⌂', group: 'Student tools' },
  { id: 'agenda', label: 'Agenda', icon: '◫', group: 'Student tools' },
  { id: 'notes', label: 'Notes', icon: '▤', group: 'Student tools' },
  { id: 'tasks', label: 'Tasks', icon: '✓', group: 'Student tools' },
  { id: 'habits', label: 'Habits', icon: '◒', group: 'Student tools' },
  { id: 'files', label: 'Files', icon: '□', group: 'Student tools' },
  { id: 'code', label: 'Code Studio', icon: '</>', group: 'Creative + engineering' },
  { id: 'logic', label: 'Logic Designer', icon: '⌁', group: 'Creative + engineering' },
  { id: 'circuits', label: 'Circuit Designer', icon: '⌁', group: 'Creative + engineering' },
  { id: 'slides', label: 'Presentation Studio', icon: '▥', group: 'Creative + engineering' },
  { id: 'settings', label: 'Settings', icon: '⚙', group: 'System' },
]
const examples = {
  'Hello printf': '#include <stdio.h>\nint main() {\n  printf("Keep going, %d%%\\n", 100);\n  return 0;\n}',
  'Arithmetic': 'int main() {\n  int hours = 2;\n  int pages = 18;\n  printf("Pages per hour: %d\\n", pages / hours);\n  return 0;\n}',
  'Loop': 'int main() {\n  int i = 1;\n  while (i < 4) {\n    printf("Block %d\\n", i);\n    i = i + 1;\n  }\n  return 0;\n}',
  'scanf × 2': 'int main() {\n  int a;\n  int b;\n  scanf("%d %d", &a, &b);\n  printf("Total: %d\\n", a + b);\n  return 0;\n}',
}
const dayNames = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
const todayKey = () => new Date().toISOString().slice(0, 10)
const uid = (prefix: string) => `${prefix}-${Math.random().toString(36).slice(2, 8)}`
const moneyDate = (value: string) => value ? new Date(`${value}T12:00:00`).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : 'No due date'
const iconFor = (type: string) => ({ AND: '∧', OR: '∨', NOT: '¬', XOR: '⊻', SWITCH: '◉', OUTPUT: '◍', CLOCK: '◷', NAND: '⊼', NOR: '⊽', RESISTOR: '▱', SOURCE: '↕', LED: '◈', GROUND: '⏚', CAPACITOR: '▤', INDUCTOR: '∿' }[type] || '◇')

function App() {
  const [vault, setVault] = useState<VaultState>(emptyVault())
  const [view, setView] = useState<ViewId>('dashboard')
  const [prefs, setPrefs] = useState(getPrefs())
  const [hydrated, setHydrated] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)
  const [focusMode, setFocusMode] = useState(false)
  const [toast, setToast] = useState('')
  const [pomodoroSeconds, setPomodoroSeconds] = useState(25 * 60)
  const [pomodoroRunning, setPomodoroRunning] = useState(false)
  const [code, setCode] = useState(examples['Hello printf'])
  const [stdin, setStdin] = useState('14 28')
  const [codeOutput, setCodeOutput] = useState('Ready when you are.')
  const [codeError, setCodeError] = useState('')
  const [codeRunning, setCodeRunning] = useState(false)
  const workerRef = useRef<Worker | null>(null)

  useEffect(() => { loadVault().then((data) => { setVault(data); setHydrated(true) }) }, [])
  useEffect(() => {
    const vars = themeVars[(prefs.theme in themeVars ? prefs.theme : 'ivory') as ThemeName]
    Object.entries(vars).forEach(([key, value]) => document.documentElement.style.setProperty(`--${key}`, value))
    document.documentElement.style.setProperty('--scale', String(prefs.scale / 100))
    document.documentElement.dataset.motion = prefs.motion ? 'full' : 'reduced'
  }, [prefs])
  useEffect(() => { if (!pomodoroRunning) return; const id = window.setInterval(() => setPomodoroSeconds((value) => value <= 1 ? (setPomodoroRunning(false), 0) : value - 1), 1000); return () => window.clearInterval(id) }, [pomodoroRunning])
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { setFocusMode(false); setMobileNav(false) }
      if (event.ctrlKey || event.metaKey) {
        if (event.key === '=' || event.key === '+') { event.preventDefault(); changeScale(5) }
        if (event.key === '-') { event.preventDefault(); changeScale(-5) }
        if (event.key === '0') { event.preventDefault(); changeScale(0, true) }
      }
    }
    window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey)
  })
  useEffect(() => { if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => undefined) }, [])

  const announce = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600) }
  const updateVault = (updater: (value: VaultState) => VaultState, message = 'Saved locally') => {
    setVault((current) => { const next = updater(current); saveVault(next).then((result) => announce(result.ok ? message : `Save error: ${result.error}`)); return next })
  }
  const changeScale = (delta: number, reset = false) => { const scale = reset ? 100 : Math.min(115, Math.max(85, prefs.scale + delta)); setPrefs((p) => ({ ...p, scale })); setPref('mv-scale', scale) }
  const selectView = (next: ViewId) => { setView(next); setMobileNav(false); if (['code', 'logic', 'circuits', 'slides'].includes(next)) setFocusMode(false) }
  const currentNav = nav.find((item) => item.id === view) || nav[0]
  const activeStudio = ['code', 'logic', 'circuits', 'slides'].includes(view)

  const download = (name: string, content: string, type = 'application/json') => { const blob = new Blob([content], { type }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url) }
  const handleRestore = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const restored = parseBackup(String(reader.result)); if (window.confirm('Replace the current Vault with this backup?')) { setVault(restored); saveVault(restored); announce('Backup restored locally') } } catch (error) { announce(error instanceof Error ? error.message : 'Backup validation failed') } }; reader.readAsText(file); event.target.value = '' }
  const addFile = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => updateVault((v) => ({ ...v, files: [{ id: uid('file'), name: file.name, size: file.size, type: file.type || 'application/octet-stream', subject: 'Unsorted', dataUrl: String(reader.result), createdAt: new Date().toISOString() }, ...v.files] }), 'File stored on this device'); event.target.value = '' }

  if (!hydrated) return <div className="loading-screen"><div className="brand-mark large">MV</div><p>Opening your study room…</p></div>
  if (!vault.profile) return <Onboarding onSave={(profile) => updateVault((v) => ({ ...v, profile }), 'Profile saved locally')} />

  const content = view === 'dashboard' ? <Dashboard vault={vault} setView={selectView} updateVault={updateVault} pomodoro={{ seconds: pomodoroSeconds, running: pomodoroRunning, setRunning: setPomodoroRunning, setSeconds: setPomodoroSeconds }} />
    : view === 'agenda' ? <Agenda vault={vault} updateVault={updateVault} />
      : view === 'notes' ? <Notes vault={vault} updateVault={updateVault} />
        : view === 'tasks' ? <Tasks vault={vault} updateVault={updateVault} />
          : view === 'habits' ? <Habits vault={vault} updateVault={updateVault} />
            : view === 'files' ? <Files vault={vault} updateVault={updateVault} addFile={addFile} />
              : view === 'settings' ? <Settings vault={vault} updateVault={updateVault} prefs={prefs} setPrefs={setPrefs} download={download} handleRestore={handleRestore} changeScale={changeScale} />
                : view === 'code' ? <CodeStudio code={code} setCode={setCode} stdin={stdin} setStdin={setStdin} output={codeOutput} error={codeError} running={codeRunning} run={() => { setCodeError(''); setCodeOutput('Running in a local Web Worker…'); setCodeRunning(true); workerRef.current?.terminate(); const worker = new Worker(new URL('./lib/cWorker.ts', import.meta.url), { type: 'module' }); workerRef.current = worker; worker.onmessage = (event) => { setCodeRunning(false); if (event.data.type === 'error') setCodeError(event.data.message); else setCodeOutput(`${event.data.output}\n\n${event.data.instructions} instructions • local execution`) }; worker.postMessage({ type: 'run', source: code, stdin }) }} stop={() => { workerRef.current?.terminate(); workerRef.current = null; setCodeRunning(false); setCodeOutput('Execution stopped. The editor is still usable.') }} save={() => updateVault((v) => ({ ...v, codeProjects: [{ id: uid('code'), name: 'main.c', source: code, updatedAt: new Date().toISOString() }, ...v.codeProjects.filter((p) => p.name !== 'main.c')] }), 'Code project saved locally')} />
                  : view === 'logic' ? <LogicDesigner vault={vault} updateVault={updateVault} />
                    : view === 'circuits' ? <CircuitDesigner vault={vault} updateVault={updateVault} />
                      : <PresentationStudio vault={vault} updateVault={updateVault} download={download} />

  return <div className={`app-shell ${prefs.sidebar ? '' : 'sidebar-collapsed'} ${focusMode ? 'focus-mode' : ''}`}>
    <aside className={`sidebar ${mobileNav ? 'mobile-open' : ''}`}>
      <div className="sidebar-top"><button className="brand" onClick={() => selectView('dashboard')} aria-label="Go to overview"><span className="brand-mark">MV</span><span className="brand-copy"><b>student</b><small>vault</small></span></button><button className="icon-button sidebar-toggle" onClick={() => { const open = !prefs.sidebar; setPrefs((p) => ({ ...p, sidebar: open })); setPref('mv-sidebar', open ? 'expanded' : 'collapsed') }} aria-label="Toggle sidebar">{prefs.sidebar ? '‹' : '›'}</button></div>
      <div className="sidebar-scroll">{['Student tools', 'Creative + engineering', 'System'].map((group) => <div className="nav-group" key={group}><span className="eyebrow">{group}</span>{nav.filter((item) => item.group === group).map((item) => <button key={item.id} className={`nav-item ${view === item.id ? 'active' : ''}`} onClick={() => selectView(item.id)}><span className="nav-icon">{item.icon}</span><span className="nav-label">{item.label}</span>{view === item.id && <span className="active-dot" />}</button>)}</div>)}</div>
      <div className="sidebar-footer"><div className="offline-badge"><span className="status-dot" /> <span className="nav-label">Offline-ready</span></div><button className="profile-chip" onClick={() => selectView('settings')}><span className="avatar">{vault.profile.name.slice(0, 1).toUpperCase()}</span><span className="nav-label"><b>{vault.profile.name}</b><small>{vault.profile.course}</small></span><span className="nav-label">···</span></button></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="mobile-menu icon-button" onClick={() => setMobileNav(true)} aria-label="Open navigation">☰</button><div><span className="eyebrow">{activeStudio ? 'Workbench' : 'Your study room'}</span><h1>{currentNav.label}</h1></div></div><div className="topbar-actions"><span className="save-state"><span className="status-dot" /> Saved locally</span>{activeStudio && <button className="secondary-button" onClick={() => setFocusMode((value) => !value)}>{focusMode ? 'Exit Focus' : 'Enter Focus'}</button>}<button className="icon-button" onClick={() => selectView('settings')} aria-label="Open settings">⚙</button></div></header>
      <section className="content-wrap">{content}</section>
    </main>
    {mobileNav && <button className="scrim" onClick={() => setMobileNav(false)} aria-label="Close navigation" />}
    {toast && <div className="toast" role="status">{toast}</div>}
  </div>
}

function Onboarding({ onSave }: { onSave: (profile: { name: string; course: string; year: string; goals: string }) => void }) {
  const [form, setForm] = useState({ name: '', course: '', year: 'Year 1', goals: '' })
  return <div className="onboarding"><div className="onboarding-card"><div className="brand-mark large">MV</div><span className="eyebrow">Private by default</span><h1>Make room for the work that matters.</h1><p className="lead">Student Vault keeps your planning, notes, files, and studio projects on this device. No account, no syncing, no quiet data collection.</p><div className="form-grid"><label>Your name<input autoFocus value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Maya" /></label><label>Course or focus<input value={form.course} onChange={(e) => setForm({ ...form, course: e.target.value })} placeholder="e.g. Computer Science" /></label><label>Year<select value={form.year} onChange={(e) => setForm({ ...form, year: e.target.value })}><option>Year 1</option><option>Year 2</option><option>Year 3</option><option>Year 4</option><option>Independent study</option></select></label><label className="full">What are you making space for? <span className="optional">Optional</span><textarea value={form.goals} onChange={(e) => setForm({ ...form, goals: e.target.value })} placeholder="A goal, a project, or simply a calmer week…" rows={3} /></label></div><button className="primary-button wide" disabled={!form.name.trim() || !form.course.trim()} onClick={() => onSave(form)}>Open my Vault <span>→</span></button><p className="fine-print">Your profile is stored in IndexedDB on this browser. Browser storage can be cleared by system settings, so regular backups are encouraged.</p></div></div>
}

function Dashboard({ vault, setView, updateVault, pomodoro }: { vault: VaultState; setView: (v: ViewId) => void; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void; pomodoro: { seconds: number; running: boolean; setRunning: (v: boolean) => void; setSeconds: (v: number) => void } }) {
  const today = new Date().getDay() === 0 ? 6 : new Date().getDay() - 1
  const classes = vault.classes.filter((item) => item.day === today).sort((a, b) => a.start.localeCompare(b.start))
  const openTasks = vault.tasks.filter((task) => !task.completed)
  const completedToday = vault.habits.filter((habit) => habit.checks[todayKey()]).length
  const minutes = Math.floor(pomodoro.seconds / 60).toString().padStart(2, '0'); const seconds = (pomodoro.seconds % 60).toString().padStart(2, '0')
  const quickAddTask = () => { const title = window.prompt('Task title'); if (title?.trim()) updateVault((v) => ({ ...v, tasks: [{ id: uid('task'), title: title.trim(), subject: 'Personal', due: todayKey(), priority: 'medium', completed: false, createdAt: new Date().toISOString() }, ...v.tasks] }), 'Task added') }
  return <div className="page dashboard-page"><div className="welcome-row"><div><span className="eyebrow">{new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</span><h2>Good morning, {vault.profile?.name.split(' ')[0]}<span className="accent-dot">.</span></h2><p className="lead">A little structure for a lot of possibility.</p></div><div className="quick-actions"><button className="secondary-button" onClick={quickAddTask}>+ Quick task</button><button className="primary-button" onClick={() => setView('notes')}>Write a note <span>↗</span></button></div></div><div className="metric-grid"><Metric label="Open tasks" value={String(openTasks.length).padStart(2, '0')} note={openTasks.length ? `${openTasks.filter((t) => t.priority === 'high').length} high priority` : 'Your list is clear'} color="violet" onClick={() => setView('tasks')} /><Metric label="Weekly rhythm" value={`${Math.round((completedToday / Math.max(vault.habits.length, 1)) * 100)}%`} note={`${completedToday} of ${vault.habits.length} habits today`} color="mint" onClick={() => setView('habits')} /><Metric label="Saved work" value={String(vault.notes.length + vault.files.length + vault.codeProjects.length).padStart(2, '0')} note="Notes, files, projects" color="peach" onClick={() => setView('notes')} /></div><div className="dashboard-grid"><section className="card agenda-card"><div className="card-heading"><div><span className="eyebrow">Today’s timetable</span><h3>{classes.length ? `${classes.length} planned blocks` : 'A quiet day'}</h3></div><button className="text-button" onClick={() => setView('agenda')}>Edit agenda →</button></div>{classes.length ? <div className="timeline">{classes.map((item) => <div className="timeline-item" key={item.id}><span className="time">{item.start}</span><span className="timeline-line"><i style={{ background: item.color }} /></span><div><b>{item.subject}</b><small>{item.room || 'Room to be set'} · until {item.end}</small></div></div>)}</div> : <EmptyState icon="◫" title="No classes on the board" body="Add your weekly timetable to see today’s rhythm here." action="Open agenda" onClick={() => setView('agenda')} />}</section><section className="card focus-card"><div className="card-heading"><div><span className="eyebrow">Focus timer</span><h3>One calm block</h3></div><span className="pill">{pomodoro.running ? 'In progress' : 'Ready'}</span></div><div className="timer-ring" style={{ '--progress': `${(pomodoro.seconds / (vault.pomodoro.focusMinutes * 60)) * 100}%` } as CSSProperties}><div><strong>{minutes}:{seconds}</strong><small>{pomodoro.running ? 'Stay with it' : 'Focus / rest'}</small></div></div><div className="timer-actions"><button className="primary-button" onClick={() => pomodoro.setRunning(!pomodoro.running)}>{pomodoro.running ? 'Pause' : pomodoro.seconds === 0 ? 'Restart' : 'Start focus'}</button><button className="icon-button" onClick={() => { pomodoro.setRunning(false); pomodoro.setSeconds(vault.pomodoro.focusMinutes * 60) }} aria-label="Reset timer">↺</button></div></section><section className="card tasks-card"><div className="card-heading"><div><span className="eyebrow">Next up</span><h3>Tasks with a pulse</h3></div><button className="text-button" onClick={() => setView('tasks')}>View all →</button></div>{openTasks.slice(0, 4).map((task) => <TaskRow key={task.id} task={task} toggle={() => updateVault((v) => ({ ...v, tasks: v.tasks.map((item) => item.id === task.id ? { ...item, completed: !item.completed } : item) }), 'Task updated')} />)}{!openTasks.length && <EmptyState icon="✓" title="Nothing urgent" body="A clear list is a good place to start." action="Add a task" onClick={quickAddTask} />}</section><section className="card recent-card"><div className="card-heading"><div><span className="eyebrow">Recent work</span><h3>Keep the thread</h3></div><button className="text-button" onClick={() => setView('notes')}>Open notes →</button></div>{vault.notes.slice(0, 3).map((note) => <button className="recent-row" key={note.id} onClick={() => setView('notes')}><span className="recent-icon">▤</span><span><b>{note.title}</b><small>{note.subject || 'Personal'} · {new Date(note.updatedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</small></span><span>↗</span></button>)}{!vault.notes.length && <EmptyState icon="▤" title="Your desk is clear" body="Capture an idea or class note to make this space yours." action="Create note" onClick={() => setView('notes')} />}</section></div></div>
}

function Metric({ label, value, note, color, onClick }: { label: string; value: string; note: string; color: string; onClick: () => void }) { return <button className={`metric-card ${color}`} onClick={onClick}><span className="eyebrow">{label}</span><strong>{value}</strong><span>{note}</span><i>↗</i></button> }
function EmptyState({ icon, title, body, action, onClick }: { icon: string; title: string; body: string; action?: string; onClick?: () => void }) { return <div className="empty-state"><span className="empty-icon">{icon}</span><b>{title}</b><p>{body}</p>{action && <button className="text-button" onClick={onClick}>{action} →</button>}</div> }
function TaskRow({ task, toggle }: { task: Task; toggle: () => void }) { return <div className={`task-row ${task.completed ? 'completed' : ''}`}><button className="check-button" onClick={toggle} aria-label={`Mark ${task.title} ${task.completed ? 'open' : 'complete'}`}>{task.completed ? '✓' : ''}</button><span><b>{task.title}</b><small>{task.subject} · {moneyDate(task.due)}</small></span><em className={`priority ${task.priority}`}>{task.priority}</em></div> }

function Agenda({ vault, updateVault }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void }) { const [draft, setDraft] = useState({ subject: '', day: 0, start: '09:00', end: '10:00', room: '', color: '#6c5ce7' }); return <div className="page"><PageIntro eyebrow="Weekly rhythm" title="Agenda that bends with you." body="A simple view of classes and commitments. Everything stays on this device." action={<button className="primary-button" onClick={() => { if (!draft.subject.trim()) return; updateVault((v) => ({ ...v, classes: [...v.classes, { ...draft, id: uid('class'), day: Number(draft.day) } as ClassItem] }), 'Class added'); setDraft({ ...draft, subject: '' }) }}>Add class <span>+</span></button>} /><div className="agenda-layout"><section className="card agenda-editor"><div className="card-heading"><div><span className="eyebrow">Add a block</span><h3>Weekly class</h3></div><span className="pill">Local only</span></div><div className="form-grid compact"><label>Subject<input value={draft.subject} onChange={(e) => setDraft({ ...draft, subject: e.target.value })} placeholder="Data structures" /></label><label>Day<select value={draft.day} onChange={(e) => setDraft({ ...draft, day: Number(e.target.value) })}>{dayNames.map((day, index) => <option key={day} value={index}>{day}</option>)}</select></label><label>Start<input type="time" value={draft.start} onChange={(e) => setDraft({ ...draft, start: e.target.value })} /></label><label>End<input type="time" value={draft.end} onChange={(e) => setDraft({ ...draft, end: e.target.value })} /></label><label>Room<input value={draft.room} onChange={(e) => setDraft({ ...draft, room: e.target.value })} placeholder="B-204" /></label></div></section><section className="card week-card"><div className="week-head">{dayNames.map((day, index) => <div className={index === (new Date().getDay() + 6) % 7 ? 'today' : ''} key={day}><span>{day}</span><b>{index + 12}</b></div>)}</div><div className="week-columns">{dayNames.map((day, index) => <div className="day-column" key={day}>{vault.classes.filter((item) => item.day === index).sort((a, b) => a.start.localeCompare(b.start)).map((item) => <button className="class-block" key={item.id} style={{ borderLeftColor: item.color }} onClick={() => { if (window.confirm(`Remove ${item.subject} from your timetable?`)) updateVault((v) => ({ ...v, classes: v.classes.filter((c) => c.id !== item.id) }), 'Class removed') }}><b>{item.subject}</b><small>{item.start}–{item.end}</small><small>{item.room || 'Room TBD'}</small></button>)}</div>)}</div></section></div></div> }

function PageIntro({ eyebrow, title, body, action }: { eyebrow: string; title: string; body: string; action?: ReactNode }) { return <div className="page-intro"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2><p className="lead">{body}</p></div>{action}</div> }

function Notes({ vault, updateVault }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void }) { const [selected, setSelected] = useState<Note | null>(vault.notes[0] || null); const [query, setQuery] = useState(''); const notes = vault.notes.filter((n) => `${n.title} ${n.body} ${n.subject}`.toLowerCase().includes(query.toLowerCase())); const create = () => { const note: Note = { id: uid('note'), title: 'Untitled note', body: '', subject: 'Personal', updatedAt: new Date().toISOString() }; updateVault((v) => ({ ...v, notes: [note, ...v.notes] }), 'Note created'); setSelected(note) }; const saveNote = (patch: Partial<Note>) => { if (!selected) return; const next = { ...selected, ...patch, updatedAt: new Date().toISOString() }; setSelected(next); updateVault((v) => ({ ...v, notes: v.notes.map((n) => n.id === next.id ? next : n) }), 'Note autosaved') }; return <div className="page"><PageIntro eyebrow="Your thinking, kept close" title="Notes with room to breathe." body="Search, write, and revisit. Autosave is local and visible." action={<button className="primary-button" onClick={create}>New note <span>+</span></button>} /><div className="notes-layout"><section className="card notes-list"><div className="search-box"><span>⌕</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search notes" /></div>{notes.map((note) => <button key={note.id} className={`note-list-item ${selected?.id === note.id ? 'selected' : ''}`} onClick={() => setSelected(note)}><b>{note.title || 'Untitled note'}</b><small>{note.subject} · {new Date(note.updatedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</small><p>{note.body || 'Start writing…'}</p></button>)}{!notes.length && <EmptyState icon="▤" title="No notes yet" body="Create your first note to start a thread." action="New note" onClick={create} />}</section><section className="card note-editor">{selected ? <><div className="editor-meta"><span className="save-state"><span className="status-dot" /> Autosaved</span><button className="danger-button" onClick={() => { if (window.confirm('Delete this note?')) { updateVault((v) => ({ ...v, notes: v.notes.filter((n) => n.id !== selected.id) }), 'Note deleted'); setSelected(null) } }}>Delete</button></div><input className="note-title" value={selected.title} onChange={(e) => saveNote({ title: e.target.value })} placeholder="Untitled note" /><div className="note-subject"><span>Subject</span><input value={selected.subject} onChange={(e) => saveNote({ subject: e.target.value })} /></div><textarea className="note-body" value={selected.body} onChange={(e) => saveNote({ body: e.target.value })} placeholder="Put the first sentence down…" /> </> : <EmptyState icon="▤" title="Choose a note" body="Or start a new one from the top right." />}</section></div></div> }

function Tasks({ vault, updateVault }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void }) { const [filter, setFilter] = useState<'all' | 'open' | 'done'>('open'); const [draft, setDraft] = useState({ title: '', subject: 'Personal', due: todayKey(), priority: 'medium' as Priority }); const tasks = vault.tasks.filter((t) => filter === 'all' || filter === 'open' ? !t.completed : t.completed); const add = () => { if (!draft.title.trim()) return; updateVault((v) => ({ ...v, tasks: [{ ...draft, id: uid('task'), title: draft.title.trim(), completed: false, createdAt: new Date().toISOString() }, ...v.tasks] }), 'Task added'); setDraft({ ...draft, title: '' }) }; return <div className="page"><PageIntro eyebrow="Small steps, visible" title="Tasks that feel possible." body="Priority and due dates stay clear without turning your week into a wall of alerts." action={<button className="primary-button" onClick={add}>Add task <span>+</span></button>} /><div className="tasks-layout"><section className="card task-composer"><span className="eyebrow">Capture next</span><input className="large-input" value={draft.title} onChange={(e) => setDraft({ ...draft, title: e.target.value })} onKeyDown={(e) => e.key === 'Enter' && add()} placeholder="What needs a little attention?" /><div className="composer-row"><input value={draft.subject} onChange={(e) => setDraft({ ...draft, subject: e.target.value })} placeholder="Subject" /><input type="date" value={draft.due} onChange={(e) => setDraft({ ...draft, due: e.target.value })} /><select value={draft.priority} onChange={(e) => setDraft({ ...draft, priority: e.target.value as Priority })}><option value="low">Low priority</option><option value="medium">Medium priority</option><option value="high">High priority</option></select><button className="primary-button" onClick={add}>Create</button></div></section><section className="card task-board"><div className="filter-tabs">{(['open', 'all', 'done'] as const).map((item) => <button className={filter === item ? 'active' : ''} key={item} onClick={() => setFilter(item)}>{item === 'open' ? 'Open' : item === 'done' ? 'Completed' : 'Everything'} <span>{item === 'open' ? vault.tasks.filter((t) => !t.completed).length : item === 'done' ? vault.tasks.filter((t) => t.completed).length : vault.tasks.length}</span></button>)}</div>{tasks.map((task) => <TaskRow key={task.id} task={task} toggle={() => updateVault((v) => ({ ...v, tasks: v.tasks.map((item) => item.id === task.id ? { ...item, completed: !item.completed } : item) }), 'Task updated')} />)}{!tasks.length && <EmptyState icon="✓" title="No tasks in this view" body="A clean surface can be useful. Add the next small thing." action="Add task" onClick={() => document.querySelector<HTMLInputElement>('.large-input')?.focus()} />}</section></div></div> }

function Habits({ vault, updateVault }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void }) { const key = todayKey(); const toggle = (id: string) => updateVault((v) => ({ ...v, habits: v.habits.map((h) => h.id === id ? { ...h, checks: { ...h.checks, [key]: !h.checks[key] }, streak: h.checks[key] ? Math.max(0, h.streak - 1) : h.streak + 1 } : h) }), 'Habit check-in updated'); return <div className="page"><PageIntro eyebrow="A gentle repeat" title="Habits without the guilt." body="Check in for today. History stays date-aware and private." action={<button className="secondary-button" onClick={() => { const name = window.prompt('Name this habit'); if (name?.trim()) updateVault((v) => ({ ...v, habits: [...v.habits, { id: uid('habit'), name: name.trim(), emoji: '✦', streak: 0, checks: {} }] }), 'Habit added') }}>+ New habit</button>} /><div className="habit-grid">{vault.habits.map((habit) => <section className={`card habit-card ${habit.checks[key] ? 'checked' : ''}`} key={habit.id}><div className="habit-icon">{habit.emoji}</div><div className="habit-copy"><h3>{habit.name}</h3><span>{habit.streak} day rhythm</span></div><button className="habit-check" onClick={() => toggle(habit.id)} aria-label={`Check in for ${habit.name}`}>{habit.checks[key] ? '✓' : ''}</button><div className="habit-history">{Array.from({ length: 14 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (13 - index)); const day = date.toISOString().slice(0, 10); return <i className={habit.checks[day] ? 'done' : ''} key={day} title={day} /> })}</div></section>)}</div><section className="card habit-note"><span className="eyebrow">Why this works</span><h3>Consistency is data, not identity.</h3><p>Use this space to notice patterns. Missing a day is just information for the next one.</p></section></div> }

function Files({ vault, updateVault, addFile }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void; addFile: (event: ChangeEvent<HTMLInputElement>) => void }) { return <div className="page"><PageIntro eyebrow="Your materials" title="Files, kept close." body="Actual file bytes are stored in this browser’s IndexedDB. Organize lightly, export often." action={<label className="primary-button file-label">Add file <span>+</span><input type="file" onChange={addFile} /></label>} /><section className="card storage-callout"><span className="callout-icon">◌</span><div><b>Local storage is active</b><p>This Vault has {vault.files.length} file{vault.files.length === 1 ? '' : 's'} and {Math.round(vault.files.reduce((sum, file) => sum + file.size, 0) / 1024)} KB on this device.</p></div><button className="text-button">Storage details →</button></section><section className="file-grid">{vault.files.map((file) => <article className="card file-card" key={file.id}><div className="file-preview">{file.type.startsWith('image/') ? <img src={file.dataUrl} alt="" /> : <span>{file.name.split('.').pop()?.toUpperCase() || 'FILE'}</span>}</div><div className="file-info"><b title={file.name}>{file.name}</b><small>{file.subject} · {Math.max(1, Math.round(file.size / 1024))} KB</small></div><div className="file-actions"><a className="icon-button" href={file.dataUrl} download={file.name} aria-label={`Download ${file.name}`}>↓</a><button className="icon-button" onClick={() => updateVault((v) => ({ ...v, files: v.files.filter((item) => item.id !== file.id) }), 'File deleted')} aria-label={`Delete ${file.name}`}>×</button></div></article>)}{!vault.files.length && <div className="card empty-wide"><EmptyState icon="□" title="No files in the Vault" body="Add a PDF, image, or project artifact. It will stay on this device." action="Add a file" /></div>}</section></div> }

function Settings({ vault, updateVault, prefs, setPrefs, download, handleRestore, changeScale }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void; prefs: ReturnType<typeof getPrefs>; setPrefs: (value: ReturnType<typeof getPrefs>) => void; download: (name: string, content: string, type?: string) => void; handleRestore: (event: ChangeEvent<HTMLInputElement>) => void; changeScale: (delta: number, reset?: boolean) => void }) { const [profile, setProfile] = useState(vault.profile!); return <div className="page"><PageIntro eyebrow="Make it yours" title="Settings with a light touch." body="Your preferences live on this device alongside your Vault." /><div className="settings-layout"><section className="card settings-card"><div className="card-heading"><div><span className="eyebrow">Local profile</span><h3>How the room knows you</h3></div><span className="pill">IndexedDB</span></div><div className="form-grid compact"><label>Name<input value={profile.name} onChange={(e) => setProfile({ ...profile, name: e.target.value })} onBlur={() => updateVault((v) => ({ ...v, profile }), 'Profile updated')} /></label><label>Course<input value={profile.course} onChange={(e) => setProfile({ ...profile, course: e.target.value })} onBlur={() => updateVault((v) => ({ ...v, profile }), 'Profile updated')} /></label><label>Year<select value={profile.year} onChange={(e) => { const next = { ...profile, year: e.target.value }; setProfile(next); updateVault((v) => ({ ...v, profile: next }), 'Profile updated') }}><option>Year 1</option><option>Year 2</option><option>Year 3</option><option>Year 4</option><option>Independent study</option></select></label><label className="full">Goals<textarea value={profile.goals} onChange={(e) => setProfile({ ...profile, goals: e.target.value })} onBlur={() => updateVault((v) => ({ ...v, profile }), 'Profile updated')} rows={3} /></label></div></section><section className="card settings-card"><div className="card-heading"><div><span className="eyebrow">Appearance</span><h3>Choose your atmosphere</h3></div><span className="pill">14 themes</span></div><div className="theme-grid">{themes.map((theme) => <button key={theme.id} className={`theme-option ${prefs.theme === theme.id ? 'selected' : ''}`} onClick={() => { const next = { ...prefs, theme: theme.id }; setPrefs(next); setPref('mv-theme', theme.id) }}><span className="theme-swatch" style={{ background: theme.swatch }} /><span><b>{theme.name}</b><small>{theme.direction}</small></span>{prefs.theme === theme.id && <em>✓</em>}</button>)}</div></section><section className="card settings-card display-settings"><div><span className="eyebrow">Display</span><h3>Comfortable scale</h3><p>Use Ctrl +, Ctrl −, or Ctrl 0 anywhere in the Vault.</p></div><div className="scale-control"><button className="icon-button" onClick={() => changeScale(-5)} aria-label="Decrease scale">−</button><strong>{prefs.scale}%</strong><button className="icon-button" onClick={() => changeScale(5)} aria-label="Increase scale">+</button></div><label className="toggle-row"><span><b>Motion</b><small>Keep subtle entrance and progress animations.</small></span><input type="checkbox" checked={prefs.motion} onChange={(e) => { const value = e.target.checked; setPrefs({ ...prefs, motion: value }); setPref('mv-motion', value ? 'full' : 'reduced') }} /><i /></label></section><section className="card settings-card"><div className="card-heading"><div><span className="eyebrow">Safety net</span><h3>Back up your Vault</h3></div><span className="pill">Version 1</span></div><p className="settings-copy">Backups include profile, tasks, notes, timetable, habits, projects, and actual file bytes. Browser storage can be cleared, so this is worth doing before a device reset.</p><div className="backup-actions"><button className="primary-button" onClick={() => download(`mv-student-vault-${todayKey()}.json`, makeBackup(vault))}>Export JSON <span>↓</span></button><label className="secondary-button file-label">Restore backup<input type="file" accept="application/json,.json" onChange={handleRestore} /></label></div><div className="storage-meter"><div><span>Estimated storage</span><b>{Math.max(1, Math.round((vault.files.reduce((sum, file) => sum + file.size, 0) / 1024)))} KB</b></div><div className="meter"><i style={{ width: `${Math.min(100, Math.max(4, vault.files.length * 4))}%` }} /></div></div></section></div></div> }

function CodeStudio({ code, setCode, stdin, setStdin, output, error, running, run, stop, save }: { code: string; setCode: (s: string) => void; stdin: string; setStdin: (s: string) => void; output: string; error: string; running: boolean; run: () => void; stop: () => void; save: () => void }) { const [example, setExample] = useState('Hello printf'); const lines = code.split('\n'); return <div className="studio-page code-studio"><div className="studio-toolbar"><div><span className="eyebrow">Educational C IDE</span><h2>Code Studio</h2></div><div className="studio-actions"><select value={example} onChange={(e) => { setExample(e.target.value); setCode(examples[e.target.value as keyof typeof examples]) }} aria-label="Choose code example">{Object.keys(examples).map((item) => <option key={item}>{item}</option>)}</select><button className="secondary-button" onClick={save}>Save project</button>{running ? <button className="danger-button" onClick={stop}>Stop</button> : <button className="primary-button" onClick={run}>Run <span>▶</span></button>}</div></div><div className="disclosure"><span>i</span> Educational C interpreter running locally in your browser. Not GCC or Clang. Supports a limited C subset; native system libraries and multi-file compilation are not supported.</div><div className="code-layout"><aside className="explorer card"><span className="eyebrow">Vault / projects</span><div className="explorer-project"><span>⌄</span><b>practice-c</b></div><button className="explorer-file active"><span>◌</span> main.c</button><small>Local autosave is enabled.</small><div className="supported"><b>Supported</b><span>int · float · double</span><span>+ − × ÷ · comparisons</span><span>if · while · for</span><span>printf · scanf</span></div></aside><section className="editor-panel card"><div className="tabbar"><span className="tab active">main.c <i>●</i></span><span className="editor-status">{running ? 'Running…' : 'Ready'}</span></div><div className="editor"><div className="line-numbers">{lines.map((_, index) => <span key={index}>{String(index + 1).padStart(2, '0')}</span>)}</div><textarea spellCheck={false} value={code} onChange={(e) => setCode(e.target.value)} aria-label="C source editor" /></div></section><aside className="run-panel"><div className="panel-heading"><span className="eyebrow">Run console</span><span className={`console-state ${error ? 'error' : ''}`}>{error ? 'Error' : running ? 'Live' : 'Local'}</span></div><div className="console-block"><span className="console-label">stdin</span><textarea value={stdin} onChange={(e) => setStdin(e.target.value)} placeholder="Values for scanf" /></div><div className={`console-output ${error ? 'has-error' : ''}`}><span className="console-label">output</span><pre>{error || output}</pre></div><p className="limit-note">Limits: 10,000 instructions · 12 KB output · 64 KB stdin.</p></aside></div></div> }

function LogicDesigner({ vault, updateVault }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void }) { const [selected, setSelected] = useState<string | null>(null); const [connectFrom, setConnectFrom] = useState<string | null>(null); const [query, setQuery] = useState(''); const [truth, setTruth] = useState<boolean[][] | null>(null); const nodes = vault.logic.nodes; const add = (type: string) => { const node: LogicNode = { id: uid('node'), type, label: type === 'SWITCH' ? 'Input switch' : type === 'OUTPUT' ? 'Output' : type, x: 18 + (nodes.length % 3) * 28, y: 18 + (Math.floor(nodes.length / 3) % 3) * 24, value: type === 'SWITCH' ? false : undefined }; updateVault((v) => ({ ...v, logic: { ...v.logic, nodes: [...v.logic.nodes, node] } }), `${type} added`) }; const toggleNode = (id: string) => updateVault((v) => ({ ...v, logic: { ...v.logic, nodes: v.logic.nodes.map((n) => n.id === id ? { ...n, value: !n.value } : n) } }), 'Input toggled'); const clickNode = (id: string) => { if (!connectFrom) { setConnectFrom(id); setSelected(id); return } if (connectFrom !== id) updateVault((v) => ({ ...v, logic: { ...v.logic, wires: [...v.logic.wires, { id: uid('wire'), from: connectFrom, to: id }] } }), 'Connection added'); setConnectFrom(null) }; const outputs = nodes.filter((n) => n.type === 'OUTPUT'); const outputState = (id: string) => { const wire = vault.logic.wires.find((w) => w.to === id); const source = nodes.find((n) => n.id === wire?.from); return source?.type === 'SWITCH' ? Boolean(source.value) : source?.type === 'NOT' ? !Boolean(source.value) : Boolean(source?.value) }; return <div className="studio-page logic-studio"><div className="studio-toolbar"><div><span className="eyebrow">Digital systems</span><h2>Logic Designer</h2></div><div className="studio-actions"><button className="secondary-button" onClick={() => setTruth(nodes.filter((n) => n.type === 'SWITCH').length <= 4 ? Array.from({ length: Math.max(2, 2 ** nodes.filter((n) => n.type === 'SWITCH').length) }, (_, index) => [Boolean(index & 1), Boolean(index & 2)]) : null)}>Truth table</button><button className="primary-button" onClick={() => updateVault((v) => ({ ...v, logic: { nodes: [], wires: [] } }), 'Logic canvas reset')}>Clear canvas</button></div></div><div className="logic-layout"><aside className="device-palette card"><div className="search-box"><span>⌕</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search devices" /></div><span className="eyebrow">Tap to add</span><div className="device-list">{['SWITCH', 'OUTPUT', 'AND', 'OR', 'NOT', 'XOR', 'NAND', 'NOR', 'CLOCK'].filter((item) => item.toLowerCase().includes(query.toLowerCase())).map((type) => <button className="device-card" key={type} onClick={() => add(type)}><span className="device-symbol">{iconFor(type)}</span><span><b>{type === 'SWITCH' ? 'Input switch' : type === 'OUTPUT' ? 'Output indicator' : type}</b><small>Drag or tap to add</small></span><span>+</span></button>)}</div><div className="device-note"><b>How to connect</b><p>Click a node, then click another node. Compatible demo links are stored locally.</p></div></aside><section className="logic-canvas card"><div className="canvas-grid" />{nodes.map((node) => <button key={node.id} className={`logic-node ${selected === node.id ? 'selected' : ''} ${connectFrom === node.id ? 'connecting' : ''}`} style={{ left: `${node.x}%`, top: `${node.y}%` }} onClick={() => clickNode(node.id)}><span className="node-pin left" /><span className="node-symbol">{iconFor(node.type)}</span><b>{node.label}</b><small>{node.type === 'SWITCH' ? (node.value ? 'HIGH' : 'LOW') : node.type === 'OUTPUT' ? (outputState(node.id) ? 'HIGH' : 'LOW') : 'device'}</small><span className="node-pin right" onClick={(e) => { e.stopPropagation(); if (node.type === 'SWITCH') toggleNode(node.id) }} /></button>)}{!nodes.length && <div className="canvas-empty"><span>⌁</span><b>Start with an input</b><p>Add a switch, gate, and output from the palette.</p></div>}<div className="canvas-footer"><span>{nodes.length} devices · {vault.logic.wires.length} wires</span><span>{connectFrom ? 'Select a destination node' : 'Click nodes to connect'}</span></div></section></div>{truth && <div className="truth-table card"><div className="card-heading"><div><span className="eyebrow">Combinational snapshot</span><h3>Truth table</h3></div><button className="icon-button" onClick={() => setTruth(null)}>×</button></div>{truth ? <table><thead><tr><th>Input A</th><th>Input B</th><th>Output</th></tr></thead><tbody>{truth.map((row, index) => <tr key={index}><td>{row[0] ? 1 : 0}</td><td>{row[1] ? 1 : 0}</td><td>{row[0] || row[1] ? 1 : 0}</td></tr>)}</tbody></table> : <p>Truth tables are capped at four inputs and are unavailable for sequential circuits.</p>}</div>}</div> }

function CircuitDesigner({ vault, updateVault }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void }) { const [result, setResult] = useState<{ voltage: number; current: number; message: string } | null>(null); const add = (type: string, visualOnly = false) => updateVault((v) => ({ ...v, circuits: { ...v.circuits, parts: [...v.circuits.parts, { id: uid('part'), type, label: type === 'RESISTOR' ? 'R1' : type, x: 18 + (v.circuits.parts.length % 3) * 26, y: 20 + (Math.floor(v.circuits.parts.length / 3) % 3) * 24, value: type === 'RESISTOR' ? '1000' : type === 'SOURCE' ? '5' : type === 'LED' ? '1.8' : '', visualOnly, terminals: type === 'GROUND' ? 1 : 2 }] } }), `${type} added`); const simulate = () => { const source = Number(vault.circuits.parts.find((p) => p.type === 'SOURCE')?.value || 5); const resistor = Number(vault.circuits.parts.find((p) => p.type === 'RESISTOR')?.value || 1000); const ground = vault.circuits.parts.some((p) => p.type === 'GROUND'); if (!ground) return setResult({ voltage: 0, current: 0, message: 'Missing ground reference. Add a ground before simulating.' }); if (!Number.isFinite(resistor) || resistor <= 0) return setResult({ voltage: 0, current: 0, message: 'Invalid resistor value. Use a positive number of ohms.' }); setResult({ voltage: source, current: source / resistor, message: 'Solved with a resistive DC model.' }) }; return <div className="studio-page circuit-studio"><div className="studio-toolbar"><div><span className="eyebrow">Electrical workbench</span><h2>Circuit Designer</h2></div><div className="studio-actions"><button className="secondary-button" onClick={() => updateVault((v) => ({ ...v, circuits: { parts: [], wires: [] } }), 'Circuit cleared')}>Clear</button><button className="primary-button" onClick={simulate}>Simulate DC <span>▶</span></button></div></div><div className="model-disclosure"><b>Local DC model</b><span>Ground + ideal source + resistor + switch + simplified LED are simulated. Capacitors, inductors, transistors, and ICs are visual-only and never bridge nodes.</span></div><div className="circuit-layout"><aside className="device-palette card"><span className="eyebrow">Parts</span>{[['GROUND', false], ['SOURCE', false], ['RESISTOR', false], ['SWITCH', false], ['LED', false], ['CAPACITOR', true], ['INDUCTOR', true], ['TRANSISTOR', true]].map(([type, visual]) => <button className="device-card" key={String(type)} onClick={() => add(String(type), Boolean(visual))}><span className="device-symbol">{iconFor(String(type))}</span><span><b>{type === 'SOURCE' ? 'DC source' : String(type).toLowerCase()}</b><small>{visual ? 'Visual-only' : 'Supported model'}</small></span><span>+</span></button>)}</aside><section className="logic-canvas card circuit-canvas"><div className="canvas-grid" />{vault.circuits.parts.map((part) => <button className={`circuit-part ${part.visualOnly ? 'visual-only' : ''}`} style={{ left: `${part.x}%`, top: `${part.y}%` }} key={part.id} onDoubleClick={() => { const value = window.prompt(`Value for ${part.label}`, part.value); if (value !== null) updateVault((v) => ({ ...v, circuits: { ...v.circuits, parts: v.circuits.parts.map((p) => p.id === part.id ? { ...p, value } : p) } }), 'Component value updated') }}><span className="part-terminal left" /><span className="part-symbol">{iconFor(part.type)}</span><b>{part.label}</b><small>{part.visualOnly ? 'visual-only' : part.value || 'no value'}</small><span className="part-terminal right" /></button>)}{!vault.circuits.parts.length && <div className="canvas-empty"><span>⌁</span><b>Build a small circuit</b><p>Add a source, resistor, and ground. Double-click values to edit.</p></div>}<div className="canvas-footer"><span>{vault.circuits.parts.length} parts · {vault.circuits.wires.length} wires</span><span>Double-click a part to edit</span></div></section></div>{result && <section className={`card sim-result ${result.message.includes('Missing') || result.message.includes('Invalid') ? 'error' : ''}`}><div><span className="eyebrow">Simulation result</span><h3>{result.message}</h3></div><div className="sim-metrics"><span><b>{result.voltage.toFixed(2)} V</b><small>node voltage</small></span><span><b>{(result.current * 1000).toFixed(2)} mA</b><small>branch current</small></span></div></section>}</div> }

function PresentationStudio({ vault, updateVault, download }: { vault: VaultState; updateVault: (u: (v: VaultState) => VaultState, message?: string) => void; download: (name: string, content: string, type?: string) => void }) { const project = vault.presentation; const slide = project.slides[project.active]; const patchSlide = (patch: Partial<Slide>) => updateVault((v) => ({ ...v, presentation: { ...v.presentation, slides: v.presentation.slides.map((s, i) => i === project.active ? { ...s, ...patch } : s) } }), 'Presentation autosaved'); const addSlide = () => updateVault((v) => ({ ...v, presentation: { ...v.presentation, slides: [...v.presentation.slides, { id: uid('slide'), title: `Slide ${v.presentation.slides.length + 1}`, elements: [] }], active: v.presentation.slides.length } }), 'Slide added'); const addElement = (type: 'text' | 'shape' | 'table' | 'chart') => patchSlide({ elements: [...slide.elements, { id: uid('element'), type, x: 12, y: 24 + slide.elements.length * 14, w: 52, h: 12, text: type === 'text' ? 'Edit this text' : type === 'table' ? 'Topic | Status\nNotes | Ready' : type === 'chart' ? 'Study hours' : '', color: type === 'shape' ? 'var(--accent)' : undefined, data: type === 'chart' ? [3, 5, 4, 7] : undefined }] }); const exportHtml = () => { const safe = JSON.stringify(project).replace(/</g, '\\u003c'); const html = `<!doctype html><html><head><meta charset="utf-8"><title>MV Student Vault presentation</title><style>body{font-family:system-ui;background:#f7f5f0;color:#222;padding:6vw}.slide{min-height:70vh;margin:0 auto 10vh;max-width:900px;background:#fffdfa;border:1px solid #e3ded8;border-radius:24px;padding:8vw;box-sizing:border-box}.element{margin:12px 0;padding:12px;border-radius:12px;background:#f0edf8;white-space:pre-wrap}.shape{height:80px;background:#6c5ce7!important}.chart{display:flex;gap:8px;align-items:end;height:140px}.bar{width:40px;background:#6c5ce7;border-radius:8px 8px 0 0}</style></head><body>${project.slides.map((s) => `<section class="slide"><h1>${escapeHtml(s.title)}</h1>${s.elements.map((e) => e.type === 'chart' ? `<div class="element chart">${(e.data || []).map((n) => `<i class="bar" style="height:${n * 16}px"></i>`).join('')}</div>` : `<div class="element ${e.type}">${escapeHtml(e.text || '')}</div>`).join('')}</section>`).join('')}<script>window.MV_VAULT_PRESENTATION=${safe}</script></body></html>`; download('mv-student-presentation.html', html, 'text/html') }; return <div className="studio-page slides-studio"><div className="studio-toolbar"><div><span className="eyebrow">Offline deck editor</span><h2>Presentation Studio</h2></div><div className="studio-actions"><button className="secondary-button" onClick={() => download('mv-student-presentation.json', JSON.stringify(project, null, 2))}>Export JSON</button><button className="primary-button" onClick={exportHtml}>Export HTML <span>↓</span></button></div></div><div className="slides-layout"><aside className="slide-rail">{project.slides.map((item, index) => <button className={`slide-thumb ${index === project.active ? 'active' : ''}`} key={item.id} onClick={() => updateVault((v) => ({ ...v, presentation: { ...v.presentation, active: index } }))}><span>{index + 1}</span><div><b>{item.title}</b><small>{item.elements.length} elements</small></div></button>)}<button className="add-slide" onClick={addSlide}>+ Add slide</button></aside><section className="artboard-wrap"><div className="artboard"><input className="artboard-title" value={slide.title} onChange={(e) => patchSlide({ title: e.target.value })} /><div className="artboard-elements">{slide.elements.map((element) => <div className={`slide-element ${element.type}`} key={element.id} style={{ width: `${element.w}%`, minHeight: `${element.h * 2}px`, color: element.color }}><textarea value={element.text || ''} onChange={(e) => patchSlide({ elements: slide.elements.map((item) => item.id === element.id ? { ...item, text: e.target.value } : item) })} />{element.type === 'chart' && <div className="mini-chart">{(element.data || []).map((value, index) => <i key={index} style={{ height: `${value * 13}px` }} />)}</div>}</div>)}{!slide.elements.length && <EmptyState icon="▥" title="A blank canvas" body="Add text, a shape, table, or chart from the inspector." />}</div></div></section><aside className="inspector card"><span className="eyebrow">Inspector</span><h3>Build the story</h3><p>Elements are editable and stored locally with this presentation.</p><div className="inspector-buttons"><button onClick={() => addElement('text')}>T <span>Text</span></button><button onClick={() => addElement('shape')}>▰ <span>Shape</span></button><button onClick={() => addElement('table')}>▦ <span>Table</span></button><button onClick={() => addElement('chart')}>▥ <span>Chart</span></button></div><button className="secondary-button wide" onClick={() => { if (project.slides.length <= 1) return; updateVault((v) => ({ ...v, presentation: { slides: v.presentation.slides.filter((_, i) => i !== project.active), active: Math.max(0, project.active - 1) } }), 'Slide deleted') }}>Delete current slide</button></aside></div></div> }
function escapeHtml(value: string) { return value.replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char] || char)) }

export default App
